"""Opt-in sharing of identical closed, stateless GN field-group calls.

Only value outputs are eligible. All input expression identities and socket
types must match, and a fixed allowlist must cover the complete dependency
closure. Anonymous captures, external-object reads, simulations, bakes, tools,
animation and unknown nodes are deliberately outside this transformation.
"""
from . import field_compaction as fields


VALUE_SOCKETS = frozenset(('NodeSocketFloat','NodeSocketInt','NodeSocketBool','NodeSocketVector'))
SAFE_NODES = frozenset(fields.PURE_PROPERTIES) | frozenset((
    'NodeGroupInput','NodeGroupOutput','NodeFrame','NodeReroute','GeometryNodeGroup',
    'GeometryNodeInputNamedAttribute','GeometryNodeInputPosition','GeometryNodeInputIndex',
    'GeometryNodeCornersOfFace','GeometryNodeVertexOfCorner','GeometryNodeOffsetCornerInFace',
    'GeometryNodeEdgesOfCorner','GeometryNodeInputMeshEdgeVertices',
    'GeometryNodeInputMeshEdgeNeighbors','GeometryNodeInputMeshVertexNeighbors',
    'GeometryNodeInputMeshIsland','GeometryNodeInputShortestEdgePaths',
    'GeometryNodeMeshLine','GeometryNodeMeshGrid','GeometryNodeMeshCircle',
    'GeometryNodeSetPosition','GeometryNodeSeparateGeometry','GeometryNodeJoinGeometry',
    'GeometryNodeStoreNamedAttribute','GeometryNodeRemoveAttribute','GeometryNodeSortElements',
    'GeometryNodeDuplicateElements','GeometryNodeDeleteGeometry','GeometryNodeMergeByDistance',
    'GeometryNodeRepeatInput','GeometryNodeRepeatOutput','GeometryNodeIndexSwitch',
    'GeometryNodeSampleNearest','GeometryNodeSampleCurve','GeometryNodeBlurAttribute',
))


class FieldCallIndex(fields.Index):
    def __init__(self, tree):
        super().__init__(tree)
        self._closed = {}

    def _safe_closure(self, tree, ancestors=frozenset()):
        if tree in self._closed:
            return self._closed[tree]
        if tree in ancestors:
            return False
        safe = tree.animation_data is None and not any(
            n.bl_idname not in SAFE_NODES for n in tree.nodes)
        safe = safe and not any(l.is_muted or not l.is_valid for l in tree.links)
        safe = safe and all(self._safe_closure(n.node_tree, ancestors | {tree})
                            for n in tree.nodes if n.type == 'GROUP' and n.node_tree)
        self._closed[tree] = safe
        return safe

    def pure(self, node):
        if node.type == 'GROUP' and node.node_tree and not node.mute:
            outputs = [s for s in node.node_tree.interface.items_tree
                       if s.item_type == 'SOCKET' and s.in_out == 'OUTPUT']
            if outputs and all(s.socket_type in VALUE_SOCKETS for s in outputs) and self._safe_closure(node.node_tree):
                return ('closed field call', node.node_tree.as_pointer())
        return super().pure(node)


